// 此方法会超时
func maxProfit(prices []int) int {
	ans := 0
	for i := 0; i < len(prices); i++ {
		for j := i + 1; j < len(prices); j++ {
			if prices[j]-prices[i] > ans {
				ans = prices[j] - prices[i]
			}
		}
	}
	return ans
}

func maxProfit(prices []int) int {
	inf := int(1e9)
	minprice := inf
	maxprofit := 0
	for _, price := range prices {
		if price-minprice > maxprofit {
			maxprofit = price - minprice
		}
		if price < minprice {
			minprice = price
		}
	}
	return maxprofit
}
